import * as React from "react";

export type RulerIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function RulerIcon({ size = 20, ...props }: RulerIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="10" width="17" height="5" rx="0.5" /><path d="M7 10 L7 12.5 M10 10 L10 13.5 M13 10 L13 12.5 M16 10 L16 13.5 M19 10 L19 12.5" />
    </svg>
  );
}
